   497→    impl Receipt {
   498→        #[doc = "Used bytes by [`ReceiptFlags`]"]
   499→        pub const fn bitflag_encoded_bytes() -> usize {
   500→            1u8 as usize
   501→        }
   502→        #[doc = "Unused bits for new fields by [`ReceiptFlags`]"]
