   205→                    self.hashed_cursor_factory.clone(),
   206→                    hashed_address,
   207→                    self.prefix_sets
   208→                        .storage_prefix_sets
   209→                        .get(&hashed_address)
   210→                        .cloned()
   211→                        .unwrap_or_default(),
   212→                    #[cfg(feature = "metrics")]
   213→                    self.metrics.storage_trie.clone(),
