   227→                    return Ok(storage_ctx.create_progress_state(
   228→                        account_node_iter,
   229→                        hash_builder,
   230→                        account_root_state.last_hashed_key,
   231→                        Some(storage_state),
   232→                    ))
   233→                }
   234→            }
