   436→                // Storage root hit threshold or resumed calculation hit threshold
   437→                debug!(
   438→                    target: "trie::state_root",
   439→                    ?hashed_address,
   440→                    storage_slots_walked,
   441→                    last_storage_key = ?state.last_hashed_key,
   442→                    ?account,
   443→                    "Pausing storage root calculation"
   444→                );
